ata-transfer-heads></dd></div><div><dt>Poids moyen / animal</dt><dd data-transfer-average></dd></div></dl><p data-transfer-availability></p></div></div></fieldset><fieldset class="transfer-section"><legend>Quantité à transférer</legend><div class="form-grid"><label class="form-wide" data-field="source_unit"><span>Que souhaitez-vous transférer ? *</span><select required name="source_unit"><option value="head">Animaux vivants — têtes</option><option value="kg">Stock converti/pesé — kg</option></select></label><label data-field="quantity_heads"><span>Nombre d’animaux *</span><input min="1" type="number" name="quantity_heads"></label><label data-field="weight_stock_id"><span>Stock pesé disponible *</span><select name="weight_stock_id"><option value="">Stock pesé</option><?php foreach($formRefs['stocks'] as$c):if(empty($c['stock_id']))continue;?><option data-site="<?=e($c['site_id'])?>" data-batch="<?=e($c['batch_id'])?>" data-available="<?=e(max(0,(float)$c['quantity_kg']-(float)$c['reserved_kg']))?>" value="<?=$c['stock_id']?>"><?=e('Stock #'.$c['stock_id'].' — '.number_format(max(0,(float)$c['quantity_kg']-(float)$c['reserved_kg']),3,',',' ').' kg disponibles')?></option><?php endforeach;?></select></label><label data-field="quantity_kg"><span>Poids à transférer (kg) *</span><input required min="0.001" type="number" step="0.001" name="quantity_kg"></label></div></fieldset><details class="transfer-transport"><summary>Transport <span>— facultatif</span></summary><div class="form-grid"><label data-field="truck_plate"><span>Immatriculation du véhicule</span><input name="truck_plate"></label><label data-field="driver_name"><span>Nom du chauffeur</span><input name="driver_name"></label></div></details><p class="livestock-guide" data-livestock-context aria-live="polite"></p><div class="transfer-review" aria-live="polite"><strong data-transfer-review>Choisissez un lot et une quantité.</strong><p>Le bon devra être approuvé, puis expédié. L’enregistrement ne retire pas encore les animaux ou les kilogrammes du stock.</p></div></div><footer><button type="button" class="btn-secondary" data-workspace-modal-close><i class="bi bi-x-lg" aria-hidden="true"></i><span>Annuler</span></button><button type="submit" class="btn-primary"><i class="bi bi-check2-circle" aria-hidden="true"></i><span>Créer le bon de transfert</span></button></footer></form></section><?php endif; ?>